const auth = $input.first().json.headers?.authorization || '';
if (!auth.startsWith('Bearer ')) return [{ json: { _error: 'AUTH_MISSING_TOKEN', _status: 401 } }];
const token = auth.slice(7);
try {
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
  if (!payload.sub) throw new Error('No sub');
  if (payload.exp && Date.now()/1000 > payload.exp) throw new Error('JWT expired');
  if (!payload.tenant_id) throw new Error('No tenant_id');

  const body = $input.first().json.body || {};
  const municipio = (body.municipio || '').trim();
  if (!municipio) return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'municipio requerido' } }];

  // Slug: lowercase + sin acentos + sin espacios. Determinista.
  const slug = municipio.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 60);
  if (!slug) return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'municipio slug vacio tras normalizar' } }];

  return [{ json: {
    user_id: payload.sub,
    tenant_id: payload.tenant_id,
    role: payload.role || 'architect',
    municipio_nombre: municipio,
    municipio_slug: slug,
    provincia: (body.provincia || '').trim() || null,
    comunidad_autonoma: (body.comunidad_autonoma || '').trim() || null,
    requested_by: body.requested_by || payload.sub,
    request_id: 'req_' + Math.random().toString(36).slice(2, 10)
  }}];
} catch (e) {
  return [{ json: { _error: 'AUTH_INVALID_TOKEN', _status: 401, _details: e.message } }];
}

// ADDENDUM 2 Bloque 5 fix: Jina Search/Reader paid/auth en 2026. Salimos
// a LLM-only: el modelo genera reglas plausibles para el municipio basandose
// en su conocimiento general de normativa espaniola (CTE, Decretos CAM,
// PGOU tipico). El campo source_doc lo marca como auto-generado. El usuario
// puede revisar y editar las reglas tras la carga inicial.
const sess = $('Decode JWT + Validate').first().json;
return [{ json: {
  tenant_id: sess.tenant_id,
  municipio_slug: sess.municipio_slug,
  municipio_nombre: sess.municipio_nombre,
  provincia: sess.provincia,
  comunidad_autonoma: sess.comunidad_autonoma,
  requested_by: sess.requested_by,
  request_id: sess.request_id
}}];

const llm = $('Extract PGOU (gpt-4o)');
const sess = $('Decode JWT + Validate').first().json;
const execMeta = {
  tenant_id: sess.tenant_id,
  municipio_slug: sess.municipio_slug,
  municipio_nombre: sess.municipio_nombre,
  provincia: sess.provincia,
  comunidad_autonoma: sess.comunidad_autonoma,
  request_id: sess.request_id
};

let rules = [];
try {
  if (!llm.isExecuted) throw new Error('LLM no ejecutado');
  const r = llm.first().json;
  const content = r?.choices?.[0]?.message?.content;
  if (!content) throw new Error('LLM sin choices[0].message.content');
  const parsed = typeof content === 'string' ? JSON.parse(content) : content;
  rules = Array.isArray(parsed?.rules) ? parsed.rules : [];
} catch (e) {
  return [{ json: { ...execMeta, _llm_failed: true, _details: 'LLM extraction failed: ' + e.message } }];
}

if (rules.length === 0) {
  return [{ json: { ...execMeta, _llm_failed: true, _details: 'LLM devolvio 0 reglas' } }];
}

const ALLOWED_CAT = new Set(['tramite_licencia','compatibilidad_uso','alturas_volumenes','retranqueos_distancias','ocupacion_parcela','ascensor_obligatorio','accesibilidad','eficiencia_energetica','habitabilidad_minima','patios_ventilacion','aparcamiento_obligatorio','proteccion_patrimonio','ite_iee','horario_obras','gestion_rcd','tasas_andamios_vados','instalaciones_servicios','otros']);
const ALLOWED_SEV = new Set(['critico','importante','recomendable','informativo']);
const ALLOWED_LIC = new Set(['comunicacion_previa','declaracion_responsable','licencia_obra_menor','licencia_obra_mayor','sin_licencia','depende']);

const seenKeys = new Set();
const cleaned = [];
for (const r of rules) {
  if (!r?.rule_title || !r?.rule_description) continue;
  let key = (r.rule_key || r.rule_title).toString().normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 50);
  if (!key) continue;
  // Evitar duplicados dentro del mismo batch
  let unique = key;
  let n = 1;
  while (seenKeys.has(unique)) { unique = key + '_' + (++n); }
  seenKeys.add(unique);
  const cat = ALLOWED_CAT.has(r.rule_category) ? r.rule_category : 'otros';
  const sev = ALLOWED_SEV.has(r.severity) ? r.severity : 'importante';
  const lic = r.license_implication && ALLOWED_LIC.has(r.license_implication) ? r.license_implication : null;
  cleaned.push({
    tenant_id: execMeta.tenant_id,
    municipio_slug: execMeta.municipio_slug,
    municipio_nombre: execMeta.municipio_nombre,
    provincia: execMeta.provincia || '',
    ccaa: execMeta.comunidad_autonoma || '',
    rule_key: unique,
    rule_category: cat,
    rule_title: r.rule_title.slice(0, 200),
    rule_description: r.rule_description.slice(0, 1500),
    normative_reference: r.normative_reference || null,
    normative_url: r.normative_url || null,
    applies_to: r.applies_to || {},
    triggers: r.triggers || {},
    license_implication: lic,
    pitfalls: Array.isArray(r.pitfalls) ? r.pitfalls : [],
    severity: sev,
    source_doc: 'agent_normativa_fetch via gpt-4o knowledge (no web scrape)'
  });
}

if (cleaned.length === 0) {
  return [{ json: { ...execMeta, _llm_failed: true, _details: 'Tras saneamiento quedaron 0 reglas validas' } }];
}

return cleaned.map(rule => ({ json: { ...rule, _meta: execMeta, _total: cleaned.length } }));

// Agregamos los inserts y devolvemos un solo item con counters + meta para los siguientes nodos.
const rows = $('Parse + Sanitize Rules').all();
const meta = rows[0]?.json?._meta;
const total = rows.length;
if (!meta) return [{ json: { _error: 'NO_META', total: 0 } }];
return [{ json: { ...meta, rules_extracted: total } }];
